})
const snapshot = (
  mode: 'light' | 'dark' | 'high-contrast',
  revision: number,
  forcedColors = false,
) =>
  resolveTheme({
    registry: createThemeRegistry(),
    selection: { mode, density: 'comfortable' },
    environment: { forcedColors },
    revision,
  })
const context = (phase = 'prepare', revision = 1, generation = 1) => ({
  version: 1,
  requestId: 'window/' + generation,
